import fs from "node:fs";
import path from "node:path";

// Check common output folders generated by TanStack Start / Nitro
const dirs = ["dist/client", ".output/public", "dist"];

for (const dir of dirs) {
  if (!fs.existsSync(dir)) continue;

  // 1. If TanStack Start generated _shell.html in SPA mode, copy it to index.html and 200.html
  const shellPath = path.join(dir, "_shell.html");
  const indexPath = path.join(dir, "index.html");
  if (fs.existsSync(shellPath) && !fs.existsSync(indexPath)) {
    fs.copyFileSync(shellPath, indexPath);
  }

  // 2. Remove _worker.js so Cloudflare Pages serves pure static files (0ms Worker CPU = No Error 1102)
  const workerPath = path.join(dir, "_worker.js");
  if (fs.existsSync(workerPath)) {
    fs.rmSync(workerPath, { recursive: true, force: true });
    console.log(`Removed ${workerPath} to disable Cloudflare Worker SSR`);
  }
}